package com.anamcara.controller;
import com.anamcara.model.SiteContent;import com.anamcara.repository.SiteContentRepository;import com.anamcara.service.S3MediaService;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.io.IOException;import java.util.List;
@RestController @RequestMapping("/api/content")public class SiteContentController{private final SiteContentRepository repository;private final S3MediaService media;public SiteContentController(SiteContentRepository repository,S3MediaService media){this.repository=repository;this.media=media;}@GetMapping public List<SiteContent>all(){return repository.findAll();}
@PostMapping(consumes="multipart/form-data")public SiteContent create(@RequestParam String contentType,@RequestParam(defaultValue="")String title,@RequestParam(defaultValue="")String testimonial,@RequestParam(defaultValue="")String name,@RequestParam(defaultValue="")String company,@RequestParam(required=false)MultipartFile file,@RequestParam(required=false,name="media")MultipartFile legacyMedia)throws IOException{MultipartFile upload=file!=null?file:legacyMedia;if(!contentType.equals("GALLERY")&&!contentType.equals("TESTIMONIAL"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid content type.");if(contentType.equals("GALLERY")&&(upload==null||upload.isEmpty()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a photo or video.");if(contentType.equals("TESTIMONIAL")&&(testimonial.isBlank()||name.isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Testimonial and name are required.");SiteContent c=new SiteContent();c.contentType=contentType;c.title=title.trim();c.testimonial=testimonial.trim();c.name=name.trim();c.company=company.trim();c.mediaType="";c.mediaUrl="";if(upload!=null&&!upload.isEmpty())try{var stored=media.store(upload);c.mediaType=stored.mediaType();c.mediaUrl="/api/uploads/"+stored.key();}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}return repository.save(c);}}
